}

// ── Helper: create arrow (line + cone) ──
function makeArrow(from, to, color, headSize = 0.08) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  dir.normalize();
  const pts = [from.clone(), to.clone().sub(dir.clone().multiplyScalar(headSize))];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  const coneGeo = new THREE.ConeGeometry(headSize * 0.5, headSize, 8);
  const coneMat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(coneGeo, coneMat);
  cone.position.copy(to);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
  return { line, cone };
}

