function makeBrace(x, yCenter, height) {
  const pts = [];
  const h = height / 2;
  const w = 0.12;
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const yy = yCenter + h - t * height;
    let xx = x;
    const rel = (yy - yCenter) / h;
    if (Math.abs(rel) > 0.85) xx = x - w * 0.3 * (1 - Math.abs(rel)) / 0.15;
    else if (Math.abs(rel) > 0.3) xx = x - w;
    else xx = x - w * 1.4;
    pts.push(new THREE.Vector3(xx, yy, 0));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color: 0x333333 });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  return line;
}

