// @FIGURE_CODE_BEGIN
// ── Element spec ──
// Gray constant box: BoxGeometry(2.2, 0.7, 0.5) at (-6, 0, 0) color #c8ccd0
// AdaIN pair #1: two thin boxes (0.14, 0.65, 0.4) teal+slate at (-4.3, 0, 0)
