// AdaIN pair #2: at (-1.3, 0, 0)
// Orange conv 8×8 #1: BoxGeometry(2.2, 1.4, 0.5) at (0.5, 0, 0)
// AdaIN pair #3: at (2.5, 0, 0)
// Orange conv 8×8 #2: BoxGeometry(2.2, 1.4, 0.5) at (4, 0, 0)
