  0xD2B48C, 0xBC8F8F, 0xF5DEB3, 0xFFE4C4, 0xFFDAB9, 0xEED5B7, 0xC4A484, 0x9C7A5B
];
for (let r = 0; r < 8; r++) {
  for (let c = 0; c < 8; c++) {
    const pg = new THREE.BoxGeometry(0.14, 0.14, 0.02);
    const pm = new THREE.MeshBasicMaterial({ color: pixColors[(r * 3 + c * 7) % pixColors.length] });
    const px = new THREE.Mesh(pg, pm);
    px.position.set((c - 3.5) * 0.16, (r - 3.5) * 0.16, 0);
    outputGroup.add(px);
  }
}
scene.add(outputGroup);

// ── Noise planes (aligned with AdaIN pairs) ──
const noise1 = makeBox(0.5, 1.0, 0.05, COL.teal, -4.3, 3, 0);
const noise2 = makeBox(0.5, 1.0, 0.05, COL.teal, -1.3, 3, 0);
const noise3 = makeBox(0.7, 1.6, 0.05, COL.teal, 2.5, 3, 0);

// ── Style branch ──
const latentZ = makeBox(1.6, 0.25, 0.3, 0xb0bec5, -6, -3, 0);
const interW = makeBox(1.6, 0.25, 0.3, COL.orange, -4.5, -3, 0);
const styleY1 = makeBox(1.6, 0.25, 0.3, COL.orange, -4.3, -2, 0);
const styleY2 = makeBox(1.6, 0.25, 0.3, COL.orange, -1.3, -2, 0);
const styleY3 = makeBox(1.6, 0.25, 0.3, COL.orange, 2.5, -2, 0);

// ── Arrows ──
// Noise arrows (downward from noise planes to AdaIN pairs)
makeArrow(new THREE.Vector3(-4.3, 2.4, 0), new THREE.Vector3(-4.3, 0.45, 0), COL.arrowLight);
makeArrow(new THREE.Vector3(-1.3, 2.4, 0), new THREE.Vector3(-1.3, 0.45, 0), COL.arrowLight);
makeArrow(new THREE.Vector3(2.5, 2.1, 0), new THREE.Vector3(2.5, 0.85, 0), COL.arrowLight);

// z → w arrow
makeArrow(new THREE.Vector3(-5.1, -3, 0), new THREE.Vector3(-5.4, -3, 0), COL.arrowDark, 0.06);

// w distribution line + upward arrows to y1, y2, y3
const distLine = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-3.6, -3, 0), new THREE.Vector3(2.5, -3, 0)
]);
const distMat = new THREE.LineBasicMaterial({ color: COL.arrowDark });
scene.add(new THREE.Line(distLine, distMat));
makeArrow(new THREE.Vector3(-4.3, -3, 0), new THREE.Vector3(-4.3, -2.2, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(-1.3, -3, 0), new THREE.Vector3(-1.3, -2.2, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(2.5, -3, 0), new THREE.Vector3(2.5, -2.2, 0), COL.arrowDark, 0.06);

// Style arrows up to AdaIN pairs (vertical)
makeArrow(new THREE.Vector3(-4.3, -1.8, 0), new THREE.Vector3(-4.3, -0.45, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(-1.3, -1.8, 0), new THREE.Vector3(-1.3, -0.45, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(2.5, -1.8, 0), new THREE.Vector3(2.5, -0.85, 0), COL.arrowDark, 0.06);

// ── Braces ──
makeBrace(-7.2, 3, 2.2);
makeBrace(-7.2, 0, 2.4);
makeBrace(-7.2, -2.5, 2.2);

// ── Channel stripe overlays on conv boxes (for noise visualization) ──
const stripeGroups = [];
function makeStripes(convMesh, count) {
  const g = new THREE.Group();
  const bw = convMesh.geometry.parameters.width;
  const bh = convMesh.geometry.parameters.height;
  for (let i = 0; i < count; i++) {
    const sg = new THREE.BoxGeometry(0.03, bh * 0.9, 0.01);
    const sm = new THREE.MeshBasicMaterial({ color: COL.teal, transparent: true, opacity: 0 });
    const s = new THREE.Mesh(sg, sm);
    s.position.set(convMesh.position.x - bw / 2 + (i + 0.5) * (bw / count), convMesh.position.y, convMesh.position.z + 0.26);
    g.add(s);
  }
  scene.add(g);
  stripeGroups.push(g);
  return g;
}
makeStripes(conv1, 12);
makeStripes(conv2, 12);
makeStripes(conv3, 12);

// ── Camera ──
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.72, target: [-0.5, 0, 0] });

// ── Labels ──
addLabel('Noise', new THREE.Vector3(-7.8, 3, 0), { fontSize: '14px', bold: true });
addLabel('Main generative<br>pipeline', new THREE.Vector3(-8.0, 0, 0), { fontSize: '13px', bold: true });
addLabel('Style', new THREE.Vector3(-7.8, -2.5, 0), { fontSize: '14px', bold: true });

addLabel('4×4×512', new THREE.Vector3(-6, 0.6, 0), { fontSize: '11px' });
addLabel('4×4×512', new THREE.Vector3(-3, 0.6, 0), { fontSize: '11px' });
addLabel('8×8×512', new THREE.Vector3(0.5, 1.0, 0), { fontSize: '11px' });
addLabel('8×8×512', new THREE.Vector3(4, 1.0, 0), { fontSize: '11px' });

addLabel('4×4×1<br>Noise <b>z<sub>1</sub></b> ⊗ ψ<sub>1</sub>', new THREE.Vector3(-4.3, 3.9, 0), { fontSize: '11px' });
addLabel('4×4×1<br>Noise <b>z<sub>2</sub></b> ⊗ ψ<sub>2</sub>', new THREE.Vector3(-1.3, 3.9, 0), { fontSize: '11px' });
addLabel('8×8×1<br>Noise <b>z<sub>3</sub></b> ⊗ ψ<sub>3</sub>', new THREE.Vector3(2.5, 4.3, 0), { fontSize: '11px' });

addLabel('Noise added to<br>every channel', new THREE.Vector3(-4.3, 1.6, 0), { fontSize: '10px', color: '#555' });

addLabel('1×1×512<br>Latent variable <b>z</b>', new THREE.Vector3(-6, -3.6, 0), { fontSize: '10px' });
addLabel('1×1×512<br>Intermediate<br>variable <b>w</b>', new THREE.Vector3(-4.5, -3.7, 0), { fontSize: '10px' });
addLabel('Fully connected<br>network', new THREE.Vector3(-5.3, -2.5, 0), { fontSize: '10px', color: '#555' });

addLabel('Style, <b>y<sub>1</sub></b>', new THREE.Vector3(-4.3, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(-4.3, -2.55, 0), { fontSize: '10px', color: '#555' });
addLabel('Style, <b>y<sub>2</sub></b>', new THREE.Vector3(-1.3, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(-1.3, -2.55, 0), { fontSize: '10px', color: '#555' });
addLabel('Style, <b>y<sub>3</sub></b>', new THREE.Vector3(2.5, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(2.5, -2.55, 0), { fontSize: '10px', color: '#555' });
addLabel('Per-channel<br>scale and offset', new THREE.Vector3(-4.3, -1.1, 0), { fontSize: '10px', color: '#555' });

// ── Interactions ──
const traceStates = ["Latent z", "Mapping network → w", "Linear transforms → y1,y2,y3", "Styles applied at synthesis blocks"];
let currentTrace = 0;

const traceContainer = document.getElementById('pipelineTraceBtns');
if (traceContainer) {
  traceStates.forEach((s, i) => {
    const btn = document.createElement('button');
    btn.textContent = s;
    btn.style.fontSize = '10px';
    btn.style.padding = '3px 6px';
    btn.addEventListener('click', () => { currentTrace = i; applyTrace(); });
    traceContainer.appendChild(btn);
  });
}

// Store original colors for highlighting
const highlightableMeshes = [latentZ, interW, styleY1, styleY2, styleY3,
  adain1.tealBox, adain1.slateBox, adain2.tealBox, adain2.slateBox,
  adain3.tealBox, adain3.slateBox, grayConst, conv1, conv2, conv3];
highlightableMeshes.forEach(m => { m.userData.origColor = m.material.color.getHex(); });

function applyTrace() {
  if (!traceContainer) return;
  const btns = traceContainer.querySelectorAll('button');
  btns.forEach((b, i) => b.classList.toggle('active', i === currentTrace));

  // Reset all to original colors
  highlightableMeshes.forEach(m => { m.material.color.setHex(m.userData.origColor); });

  const highlight = (mesh, color) => { mesh.material.color.setHex(color || 0xffdd44); };

  if (currentTrace >= 0) highlight(latentZ);
  if (currentTrace >= 1) highlight(interW);
  if (currentTrace >= 2) { highlight(styleY1); highlight(styleY2); highlight(styleY3); }
  if (currentTrace >= 3) {
    highlight(adain1.tealBox, 0x44ff88); highlight(adain1.slateBox, 0x44ff88);
    highlight(adain2.tealBox, 0x44ff88); highlight(adain2.slateBox, 0x44ff88);
    highlight(adain3.tealBox, 0x44ff88); highlight(adain3.slateBox, 0x44ff88);
  }
}
applyTrace();

// Noise scale slider
const noiseSlider = document.getElementById('noiseScale');
const noiseValSpan = document.getElementById('noiseScaleVal');

function applyNoiseScale() {
  if (!noiseSlider || !noiseValSpan) return;
  const v = parseFloat(noiseSlider.value) || 0;
  noiseValSpan.textContent = v.toFixed(2);
  const s = 0.5 + v * 0.8;
