// @FIGURE_CODE_BEGIN
// ── Element spec ──
// Gray constant box: BoxGeometry(2.2, 0.7, 0.5) at (-6, 0, 0) color #c8ccd0
// AdaIN pair #1: two rounded extruded boxes (0.14, 0.65, 0.4) teal+slate at (-4.3, 0, 0)
// Orange conv 4×4 #1: BoxGeometry(2.2, 0.7, 0.5) at (-3, 0, 0) color #c47a52
// AdaIN pair #2: at (-1.3, 0, 0)
// Orange conv 8×8 #1: BoxGeometry(2.2, 1.4, 0.5) at (0.5, 0, 0)
// AdaIN pair #3: at (2.5, 0, 0)
// Orange conv 8×8 #2: BoxGeometry(2.2, 1.4, 0.5) at (4, 0, 0)
// Output image: 8×8 grid of small boxes at (5.8, 0, 0)
// Noise planes: thin boxes (depth 0.12) at Y=+3, aligned with AdaIN x positions
// Style boxes: thin boxes at Y=-2, aligned with AdaIN x positions
// Arrows: lines with cone heads
// Braces: line paths on left side at x=-7.2

const COL = {
  gray: 0xc8ccd0, orange: 0xc47a52, teal: 0xa8dcd4, slate: 0x3a5a6e,
  arrowLight: 0x9db8c8, arrowDark: 0x3a6a7a, text: 0x1a1a1a
};

// ── Helper: create box ──
function makeBox(w, h, dp, color, x, y, z) {
  const geo = new THREE.BoxGeometry(w, h, dp);
  const mat = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  scene.add(mesh);
  return mesh;
}

// ── Helper: create rounded box (ExtrudeGeometry with rounded rect shape) ──
function makeRoundedBox(w, h, depth, radius, color, x, y, z) {
  const shape = new THREE.Shape();
  const hw = w / 2, hh = h / 2, r = Math.min(radius, hw * 0.9, hh * 0.9);
  shape.moveTo(-hw + r, -hh);
  shape.lineTo(hw - r, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + r);
  shape.lineTo(hw, hh - r);
  shape.quadraticCurveTo(hw, hh, hw - r, hh);
  shape.lineTo(-hw + r, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - r);
  shape.lineTo(-hw, -hh + r);
  shape.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
  const extrudeSettings = { depth: depth, bevelEnabled: false };
  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.translate(0, 0, -depth / 2);
  const mat = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  scene.add(mesh);
  return mesh;
}

// ── Helper: create arrow (line + cone) ──
function makeArrow(from, to, color, headSize) {
  headSize = headSize || 0.08;
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 0.01) return null;
  dir.normalize();
  const pts = [from.clone(), to.clone().sub(dir.clone().multiplyScalar(headSize))];
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  const coneGeo = new THREE.ConeGeometry(headSize * 0.5, headSize, 8);
  const coneMat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(coneGeo, coneMat);
  cone.position.copy(to);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
  return { line, cone };
}

// ── Helper: create brace ──
function makeBrace(x, yCenter, height) {
  const pts = [];
  const h = height / 2;
  const w = 0.12;
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const yy = yCenter + h - t * height;
    let xx = x;
    const rel = (yy - yCenter) / h;
    if (Math.abs(rel) > 0.85) xx = x - w * 0.3 * (1 - Math.abs(rel)) / 0.15;
    else if (Math.abs(rel) > 0.3) xx = x - w;
    else xx = x - w * 1.4;
    pts.push(new THREE.Vector3(xx, yy, 0));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color: 0x333333 });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  return line;
}

// ── Pipeline boxes ──
const grayConst = makeBox(2.2, 0.7, 0.5, COL.gray, -6, 0, 0);
const conv1 = makeBox(2.2, 0.7, 0.5, COL.orange, -3, 0, 0);
const conv2 = makeBox(2.2, 1.4, 0.5, COL.orange, 0.5, 0, 0);
const conv3 = makeBox(2.2, 1.4, 0.5, COL.orange, 4, 0, 0);

// ── AdaIN pairs (rounded teal + slate thin boxes) ──
function makeAdaINPair(x) {
  const tealBox = makeRoundedBox(0.14, 0.65, 0.4, 0.06, COL.teal, x - 0.12, 0, 0);
  const slateBox = makeRoundedBox(0.14, 0.65, 0.4, 0.06, COL.slate, x + 0.12, 0, 0);
  return { tealBox, slateBox };
}
const adain1 = makeAdaINPair(-4.3);
const adain2 = makeAdaINPair(-1.3);
const adain3 = makeAdaINPair(2.5);

// ── Output image (8×8 pixelated grid) ──
const outputGroup = new THREE.Group();
outputGroup.position.set(5.8, 0, 0);
const pixColors = [
  0x8B4513, 0xD2691E, 0xF4A460, 0xDEB887, 0x654321, 0xA0522D, 0xCD853F, 0x8B6914,
  0xD2B48C, 0xBC8F8F, 0xF5DEB3, 0xFFE4C4, 0xFFDAB9, 0xEED5B7, 0xC4A484, 0x9C7A5B
];
for (let r = 0; r < 8; r++) {
  for (let c = 0; c < 8; c++) {
    const pg = new THREE.BoxGeometry(0.14, 0.14, 0.02);
    const pm = new THREE.MeshBasicMaterial({ color: pixColors[(r * 3 + c * 7) % pixColors.length] });
    const px = new THREE.Mesh(pg, pm);
    px.position.set((c - 3.5) * 0.16, (r - 3.5) * 0.16, 0);
    outputGroup.add(px);
  }
}
scene.add(outputGroup);

// ── Noise planes (depth 0.12 for visible parallelogram in oblique) ──
const noise1 = makeBox(0.5, 1.0, 0.12, COL.teal, -4.3, 3, 0);
const noise2 = makeBox(0.5, 1.0, 0.12, COL.teal, -1.3, 3, 0);
const noise3 = makeBox(0.7, 1.6, 0.12, COL.teal, 2.5, 3, 0);

// ── Style branch ──
const latentZ = makeBox(1.6, 0.25, 0.3, 0xb0bec5, -6, -3, 0);
const interW = makeBox(1.6, 0.25, 0.3, COL.orange, -4.5, -3, 0);
const styleY1 = makeBox(1.6, 0.25, 0.3, COL.orange, -4.3, -2, 0);
const styleY2 = makeBox(1.6, 0.25, 0.3, COL.orange, -1.3, -2, 0);
const styleY3 = makeBox(1.6, 0.25, 0.3, COL.orange, 2.5, -2, 0);

// ── Arrows ──
// Noise arrows (downward from noise planes to AdaIN pairs)
makeArrow(new THREE.Vector3(-4.3, 2.4, 0), new THREE.Vector3(-4.3, 0.45, 0), COL.arrowLight);
makeArrow(new THREE.Vector3(-1.3, 2.4, 0), new THREE.Vector3(-1.3, 0.45, 0), COL.arrowLight);
makeArrow(new THREE.Vector3(2.5, 2.1, 0), new THREE.Vector3(2.5, 0.85, 0), COL.arrowLight);

// z → w arrow
makeArrow(new THREE.Vector3(-5.1, -3, 0), new THREE.Vector3(-5.4, -3, 0), COL.arrowDark, 0.06);

// w distribution line + upward arrows to y1, y2, y3
const distLine = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-3.6, -3, 0), new THREE.Vector3(2.5, -3, 0)
]);
const distMat = new THREE.LineBasicMaterial({ color: COL.arrowDark });
scene.add(new THREE.Line(distLine, distMat));
makeArrow(new THREE.Vector3(-4.3, -3, 0), new THREE.Vector3(-4.3, -2.2, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(-1.3, -3, 0), new THREE.Vector3(-1.3, -2.2, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(2.5, -3, 0), new THREE.Vector3(2.5, -2.2, 0), COL.arrowDark, 0.06);

// Style arrows up to AdaIN pairs (vertical)
makeArrow(new THREE.Vector3(-4.3, -1.8, 0), new THREE.Vector3(-4.3, -0.45, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(-1.3, -1.8, 0), new THREE.Vector3(-1.3, -0.45, 0), COL.arrowDark, 0.06);
makeArrow(new THREE.Vector3(2.5, -1.8, 0), new THREE.Vector3(2.5, -0.85, 0), COL.arrowDark, 0.06);

// ── Braces ──
makeBrace(-7.2, 3, 2.2);
makeBrace(-7.2, 0, 2.4);
makeBrace(-7.2, -2.5, 2.2);

// ── Channel stripe overlays on conv boxes (for noise visualization) ──
const stripeGroups = [];
function makeStripes(convMesh, count) {
  const g = new THREE.Group();
  const bw = convMesh.geometry.parameters.width;
  const bh = convMesh.geometry.parameters.height;
  for (let i = 0; i < count; i++) {
    const sg = new THREE.BoxGeometry(0.03, bh * 0.9, 0.01);
    const sm = new THREE.MeshBasicMaterial({ color: COL.teal, transparent: true, opacity: 0 });
    const s = new THREE.Mesh(sg, sm);
    s.position.set(convMesh.position.x - bw / 2 + (i + 0.5) * (bw / count), convMesh.position.y, convMesh.position.z + 0.26);
    g.add(s);
  }
  scene.add(g);
  stripeGroups.push(g);
  return g;
}
makeStripes(conv1, 12);
makeStripes(conv2, 12);
makeStripes(conv3, 12);

// ── Camera ─
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.72, target: [-0.5, 0, 0] });

// ── Labels ─
addLabel('Noise', new THREE.Vector3(-7.8, 3, 0), { fontSize: '14px', bold: true });
addLabel('Main generative<br>pipeline', new THREE.Vector3(-8.0, 0, 0), { fontSize: '13px', bold: true });
addLabel('Style', new THREE.Vector3(-7.8, -2.5, 0), { fontSize: '14px', bold: true });

addLabel('4×4×512', new THREE.Vector3(-6, 0.6, 0), { fontSize: '11px' });
addLabel('4×4×512', new THREE.Vector3(-3, 0.6, 0), { fontSize: '11px' });
addLabel('8×8×512', new THREE.Vector3(0.5, 1.0, 0), { fontSize: '11px' });
addLabel('8×8×512', new THREE.Vector3(4, 1.0, 0), { fontSize: '11px' });

addLabel('4×4×1<br>Noise <b>z<sub>1</sub></b> ⊗ ψ<sub>1</sub>', new THREE.Vector3(-4.3, 3.9, 0), { fontSize: '11px' });
addLabel('4×4×1<br>Noise <b>z<sub>2</sub></b> ⊗ ψ<sub>2</sub>', new THREE.Vector3(-1.3, 3.9, 0), { fontSize: '11px' });
addLabel('8×8×1<br>Noise <b>z<sub>3</sub></b> ⊗ ψ<sub>3</sub>', new THREE.Vector3(2.5, 4.3, 0), { fontSize: '11px' });

addLabel('Noise added to<br>every channel', new THREE.Vector3(-4.3, 1.6, 0), { fontSize: '10px', color: '#555' });

addLabel('1×1×512<br>Latent variable <b>z</b>', new THREE.Vector3(-6, -3.6, 0), { fontSize: '10px' });
addLabel('1×1×512<br>Intermediate<br>variable <b>w</b>', new THREE.Vector3(-4.5, -3.7, 0), { fontSize: '10px' });
addLabel('Fully connected<br>network', new THREE.Vector3(-5.6, -2.35, 0), { fontSize: '9px', color: '#555' });

addLabel('Style, <b>y<sub>1</sub></b>', new THREE.Vector3(-4.3, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(-4.3, -2.65, 0), { fontSize: '9px', color: '#555' });
addLabel('Style, <b>y<sub>2</sub></b>', new THREE.Vector3(-1.3, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(-1.3, -2.65, 0), { fontSize: '9px', color: '#555' });
addLabel('Style, <b>y<sub>3</sub></b>', new THREE.Vector3(2.5, -1.55, 0), { fontSize: '11px' });
addLabel('Linear transform<br>2 × 1 × 512', new THREE.Vector3(2.5, -2.65, 0), { fontSize: '9px', color: '#555' });
addLabel('Per-channel<br>scale and offset', new THREE.Vector3(-4.3, -1.1, 0), { fontSize: '10px', color: '#555' });

// ── Interactions ──
const traceStates = ["Latent z", "Mapping network → w", "Linear transforms → y1,y2,y3", "Styles applied at synthesis blocks"];
let currentTrace = -1;

const traceContainer = document.getElementById('pipelineTraceBtns');
if (traceContainer) {
  traceStates.forEach((s, i) => {
    const btn = document.createElement('button');
    btn.textContent = s;
    btn.style.fontSize = '10px';
    btn.style.padding = '3px 6px';
    btn.addEventListener('click', () => { currentTrace = i; applyTrace(); });
    traceContainer.appendChild(btn);
  });
}

// Store original colors for highlighting
const highlightableMeshes = [latentZ, interW, styleY1, styleY2, styleY3,
  adain1.tealBox, adain1.slateBox, adain2.tealBox, adain2.slateBox,
  adain3.tealBox, adain3.slateBox, grayConst, conv1, conv2, conv3];
highlightableMeshes.forEach(m => { m.userData.origColor = m.material.color.getHex(); });

function applyTrace() {
  if (!traceContainer) return;
  const btns = traceContainer.querySelectorAll('button');
  btns.forEach((b, i) => b.classList.toggle('active', i === currentTrace));

  // Reset all to original colors
  highlightableMeshes.forEach(m => { m.material.color.setHex(m.userData.origColor); });

  const highlight = (mesh, color) => { mesh.material.color.setHex(color || 0xffdd44); };

  if (currentTrace >= 0) highlight(latentZ);
  if (currentTrace >= 1) highlight(interW);
  if (currentTrace >= 2) { highlight(styleY1); highlight(styleY2); highlight(styleY3); }
  if (currentTrace >= 3) {
    highlight(adain1.tealBox, 0x44ff88); highlight(adain1.slateBox, 0x44ff88);
    highlight(adain2.tealBox, 0x44ff88); highlight(adain2.slateBox, 0x44ff88);
    highlight(adain3.tealBox, 0x44ff88); highlight(adain3.slateBox, 0x44ff88);
  }
}
applyTrace();

// Noise scale slider
const noiseSlider = document.getElementById('noiseScale');
const noiseValSpan = document.getElementById('noiseScaleVal');

function applyNoiseScale() {
  if (!noiseSlider || !noiseValSpan) return;
  const v = parseFloat(noiseSlider.value) || 0;
  noiseValSpan.textContent = v.toFixed(2);
  const s = 0.5 + v * 0.8;
  noise1.scale.set(s, s, 1);
  noise2.scale.set(s, s, 1);
  noise3.scale.set(s, s, 1);
  noise1.material.opacity = 0.3 + v * 0.7;
  noise2.material.opacity = 0.3 + v * 0.7;
  noise3.material.opacity = 0.3 + v * 0.7;
  noise1.material.transparent = true;
  noise2.material.transparent = true;
  noise3.material.transparent = true;
  stripeGroups.forEach(g => {
    g.children.forEach(c => { c.material.opacity = v * 0.6; });
  });
}
if (noiseSlider) {
  noiseSlider.addEventListener('input', applyNoiseScale);
  applyNoiseScale();
}

// ── Demo steps ──
const demoSteps = [
  { title: "Latent input", narration: "The 1×1×512 latent z is the only random seed for content; it sits at the start of the style branch.", trace: 0, noise: 0.5 },
  { title: "Mapping to w", narration: "The fully-connected mapping network transforms z into the intermediate w, disentangling the latent space before styles are read out.", trace: 1, noise: 0.5 },
  { title: "Three style vectors", narration: "Three independent linear transforms turn w into y1, y2, y3 (each 2×1×512 = per-channel scale and offset), one per resolution stage.", trace: 2, noise: 0.5 },
  { title: "AdaIN injection + noise sweep", narration: "Each y modulates its synthesis block via adaptive instance normalization while the ψ slider scales the additive noise.", trace: 3, noise: 0.9 }
];

let demoPlaying = false;
let demoTimeout = null;
const btnDemo = document.getElementById('btnDemo');
if (btnDemo) {
  btnDemo.addEventListener('click', () => {
    if (demoPlaying) {
      demoPlaying = false;
      clearTimeout(demoTimeout);
      btnDemo.textContent = '▶ Play Demo';
      return;
    }
    demoPlaying = true;
    btnDemo.textContent = '⏸ Stop';
    let step = 0;
    function runStep() {
      if (!demoPlaying || step >= demoSteps.length) {
        demoPlaying = false;
        if (btnDemo) btnDemo.textContent = '▶ Play Demo';
        return;
      }
      const s = demoSteps[step];
      currentTrace = s.trace;
      applyTrace();
      if (noiseSlider) { noiseSlider.value = s.noise; applyNoiseScale(); }
      showPopup(s.title, s.narration);
      step++;
      demoTimeout = setTimeout(runStep, 3000);
    }
    runStep();
  });
}

